using namespace std;

int main() {
    string st;
    cin >> st;

    int ans = 0;
    for (char c : st) {
        if (c == '4' || c == '7') {
            ++ans;
        }
    }

    cout << (ans == 4 || ans == 7 ? "YES" : "NO") << '\n';
    return 0;
}

